package com.bank.maturity.service;

import com.bank.maturity.dto.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;

@Service
@Slf4j
public class MaturityCalculatorService {

    // DateTimeFormatter is THREAD-SAFE (unlike SimpleDateFormat!)
    // Can be a static final field — shared across all threads safely
    private static final DateTimeFormatter DISPLAY_FORMAT =
        DateTimeFormatter.ofPattern("dd MMM yyyy, hh:mm a z");

    private static final DateTimeFormatter ISO_FORMAT =
        DateTimeFormatter.ISO_INSTANT;  // 2024-01-15T09:30:00Z

    public MaturityResult calculate(MaturityRequest request) {

        // ═══ LocalDate: date without time — for deposit/maturity dates ═══
        LocalDate depositDate = request.depositDate();
        // IMMUTABLE: plusMonths returns a NEW LocalDate — original unchanged!
        LocalDate maturityDate = depositDate.plusMonths(request.tenureMonths());
        // No 0-based months! January = 1, December = 12 (unlike Calendar)

        // ═══ Period: human-readable duration between two dates ═══
        Period tenure = Period.between(depositDate, maturityDate);
        String tenureText = tenure.getYears() > 0
            ? tenure.getYears() + " year" + (tenure.getYears() > 1 ? "s" : "") +
              (tenure.getMonths() > 0 ? " " + tenure.getMonths() + " months" : "")
            : tenure.getMonths() + " months";

        // ═══ ChronoUnit: days until maturity ═══
        long daysUntil = ChronoUnit.DAYS.between(LocalDate.now(), maturityDate);

        // ═══ Calculate interest ═══
        BigDecimal years = BigDecimal.valueOf(request.tenureMonths())
            .divide(BigDecimal.valueOf(12), 4, RoundingMode.HALF_UP);
        BigDecimal interest = request.principal()
            .multiply(request.annualRate())
            .multiply(years)
            .divide(new BigDecimal("100"), 2, RoundingMode.HALF_UP);
        BigDecimal maturityAmount = request.principal().add(interest);

        // ═══ Instant: UTC machine timestamp — for DB storage ═══
        // Instant = a point on the UTC timeline. No timezone. Machine-precise.
        Instant now = Instant.now();
        String utcTimestamp = ISO_FORMAT.format(now);
        log.info("Instant (UTC): {}", utcTimestamp);
        // Store Instant in DB: TIMESTAMP WITH TIME ZONE → always UTC

        // ═══ ZonedDateTime: human-readable with timezone — for display ═══
        // Same Instant, different presentation per timezone
        ZoneId zone = ZoneId.of(
            request.timezone() != null ? request.timezone() : "Asia/Kolkata");
        ZonedDateTime localTime = now.atZone(zone);
        String localTimestamp = DISPLAY_FORMAT.format(localTime);
        log.info("ZonedDateTime ({}): {}", zone, localTimestamp);
        // Mumbai: "15 Jan 2024, 03:00 PM IST"
        // London: "15 Jan 2024, 09:30 AM GMT"
        // Same instant, different display!

        // ═══ Duration: time-based amount ═══
        Duration processingTime = Duration.between(Instant.now().minusMillis(50), Instant.now());
        log.info("Processing took: {}ms", processingTime.toMillis());

        // ═══ Format maturity date for customer ═══
        String formattedMaturity = maturityDate.format(
            DateTimeFormatter.ofPattern("dd MMMM yyyy"));  // "15 July 2025"

        return new MaturityResult(
            depositDate, maturityDate, formattedMaturity, tenureText, daysUntil,
            request.principal(), interest, maturityAmount,
            utcTimestamp, localTimestamp, zone.getId());
    }
}
