// ─── File: test/.../MaturityCalculatorServiceTest.java ───
package com.bank.maturity.service;

import com.bank.maturity.dto.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.time.LocalDate;
import static org.assertj.core.api.Assertions.*;

class MaturityCalculatorServiceTest {

    MaturityCalculatorService service = new MaturityCalculatorService();

    @Test
    void shouldCalculateMaturityDateAndAmount() {
        MaturityResult result = service.calculate(new MaturityRequest(
            LocalDate.of(2024, 1, 15),  // January = 1 (not 0 like Calendar!)
            new BigDecimal("500000"),
            new BigDecimal("7.25"),
            18,  // 18 months
            "Asia/Kolkata"));

        // Maturity date: Jan 15 + 18 months = Jul 15
        assertThat(result.maturityDate()).isEqualTo(LocalDate.of(2025, 7, 15));
        assertThat(result.tenure()).isEqualTo("1 year 6 months");
        assertThat(result.maturityAmount()).isEqualByComparingTo("554375.00");
        assertThat(result.timezoneUsed()).isEqualTo("Asia/Kolkata");
    }

    @Test
    void shouldHandleDifferentTimezones() {
        MaturityResult mumbai = service.calculate(new MaturityRequest(
            LocalDate.of(2024, 1, 15), new BigDecimal("100000"),
            new BigDecimal("6.0"), 12, "Asia/Kolkata"));

        MaturityResult london = service.calculate(new MaturityRequest(
            LocalDate.of(2024, 1, 15), new BigDecimal("100000"),
            new BigDecimal("6.0"), 12, "Europe/London"));

        // Same Instant, different display timestamps
        assertThat(mumbai.timestampUtc()).isEqualTo(london.timestampUtc()); // same UTC!
        assertThat(mumbai.timezoneUsed()).isEqualTo("Asia/Kolkata");
        assertThat(london.timezoneUsed()).isEqualTo("Europe/London");
    }

    @Test
    void shouldBeThreadSafe() throws InterruptedException {
        // DateTimeFormatter is static final — THREAD SAFE
        // SimpleDateFormat would FAIL this test!
        var threads = new Thread[100];
        var results = new MaturityResult[100];

        for (int i = 0; i < 100; i++) {
            int idx = i;
            threads[i] = new Thread(() -> {
                results[idx] = service.calculate(new MaturityRequest(
                    LocalDate.of(2024, 1, 15), new BigDecimal("100000"),
                    new BigDecimal("6.0"), 12, "Asia/Kolkata"));
            });
            threads[i].start();
        }
        for (Thread t : threads) t.join();

        // All 100 concurrent results should be identical
        for (MaturityResult r : results) {
            assertThat(r.maturityDate()).isEqualTo(LocalDate.of(2025, 1, 15));
            assertThat(r.maturityAmount()).isEqualByComparingTo("106000.00");
        }
    }
}
